ImagePrecision precisionFor(const QImage &image) {
    if(image.format()==QImage::Format_RGBA32FPx4 || image.format()==QImage::Format_RGBA32FPx4_Premultiplied || image.format()==QImage::Format_RGBX32FPx4 || image.format()==QImage::Format_RGBA16FPx4 || image.format()==QImage::Format_RGBA16FPx4_Premultiplied || image.format()==QImage::Format_RGBX16FPx4)return ImagePrecision::Float32;
    return image.depth()>32 || image.format()==QImage::Format_Grayscale16?ImagePrecision::UInt16:ImagePrecision::UInt8;
}
ImageLayerInfo activeLayer(ImageDocument *doc,const QUuid &id){for(const auto &layer:doc->layers())if(layer.id==id)return layer;return {};}
QIcon toolIcon(const QString &kind) {
    QPixmap pixmap(24,24);pixmap.fill(Qt::transparent);QPainter p(&pixmap);p.setRenderHint(QPainter::Antialiasing);p.setPen(QPen(QColor("#ddd"),1.6));
    if(kind=="move"){p.drawLine(12,2,12,22);p.drawLine(2,12,22,12);p.drawPolyline(QPolygonF{{8,6},{12,2},{16,6}});p.drawPolyline(QPolygonF{{8,18},{12,22},{16,18}});p.drawPolyline(QPolygonF{{6,8},{2,12},{6,16}});p.drawPolyline(QPolygonF{{18,8},{22,12},{18,16}});}
    else if(kind=="select" || kind=="ellipseSelect"){p.setPen(QPen(QColor("#ddd"),1.6,Qt::DashLine));if(kind=="select")p.drawRect(4,4,16,16);else p.drawEllipse(3,5,18,14);}
    else if(kind=="polygon"){p.setPen(QPen(QColor("#ddd"),1.6,Qt::DashLine));p.drawPolygon(QPolygonF{{3,19},{8,3},{21,9},{16,21}});}
    else if(kind=="magnetic"){p.drawArc(4,3,16,16,0,180*16);p.drawLine(4,11,4,20);p.drawLine(20,11,20,20);p.drawLine(3,16,7,16);p.drawLine(17,16,21,16);}
    else if(kind=="quick"){p.setPen(QPen(QColor("#ddd"),1.6,Qt::DashLine));p.drawEllipse(3,3,13,13);p.setPen(QPen(QColor("#ddd"),2));p.drawLine(12,19,22,6);}
    else if(kind=="object"){p.setPen(QPen(QColor("#ddd"),1.6,Qt::DashLine));p.drawRect(3,3,18,18);p.setBrush(QColor("#ddd"));p.drawPolygon(QPolygonF{{8,7},{8,18},{11,15},{14,20},{17,18},{14,13},{18,13}});}
    else if(kind=="ruler"){p.drawRect(2,7,20,10);for(int x=5;x<22;x+=4)p.drawLine(x,7,x,12);}
    else if(kind=="slice"){p.drawLine(3,20,20,3);p.drawEllipse(2,13,7,7);p.drawEllipse(10,15,7,7);}
    else if(kind=="replace"){p.drawEllipse(2,2,10,10);p.setBrush(QColor("#ddd"));p.drawRect(14,14,8,8);p.drawLine(6,19,18,6);}
    else if(kind=="fill"){p.drawPolygon(QPolygonF{{3,12},{11,3},{20,12},{12,21}});p.drawLine(3,12,20,12);p.drawEllipse(19,17,3,5);}
    else if(kind=="sharpen")p.drawPolygon(QPolygonF{{12,3},{3,21},{21,21}});
    else if(kind=="burn"){p.setBrush(QColor("#ddd"));p.drawEllipse(4,4,15,15);p.drawLine(17,17,22,22);}
    else if(kind=="sponge"){p.drawRect(3,6,18,13);for(int x=6;x<20;x+=4){p.drawPoint(x,10);p.drawPoint(x,15);}}
    else if(kind=="lasso"){p.drawEllipse(3,4,18,12);p.drawArc(7,11,8,12,180*16,180*16);}
    else if(kind=="wand"){p.drawLine(5,21,18,8);p.drawLine(17,2,17,6);p.drawLine(21,6,23,6);p.drawLine(9,4,12,7);p.drawLine(21,10,23,12);}
    else if(kind=="crop"){p.drawPolyline(QPolygonF{{6,2},{6,18},{22,18}});p.drawPolyline(QPolygonF{{2,6},{18,6},{18,22}});}
    else if(kind=="dropper"){p.drawPolygon(QPolygonF{{3,21},{6,15},{17,4},{20,7},{9,18}});p.drawLine(14,4,20,10);}
    else if(kind=="heal"){p.translate(12,12);p.rotate(-40);p.drawRoundedRect(-4,-10,8,20,3,3);p.drawLine(-4,-3,4,-3);p.drawLine(-4,3,4,3);}
    else if(kind=="brush"){p.drawPolygon(QPolygonF{{8,16},{17,3},{21,5},{12,19}});p.setBrush(QColor("#ddd"));QPainterPath v;v.moveTo(9,15);v.cubicTo(1,13,6,21,2,22);v.cubicTo(12,23,13,19,9,15);p.drawPath(v);}
    else if(kind=="stamp"){p.drawRect(4,17,16,4);p.drawPolyline(QPolygonF{{6,17},{8,13},{8,7},{10,3},{14,3},{16,7},{16,13},{18,17}});}
    else if(kind=="eraser")p.drawPolygon(QPolygonF{{3,15},{13,4},{22,12},{12,21},{8,21}});
    else if(kind=="gradient"){QLinearGradient g(3,0,21,0);g.setColorAt(0,Qt::white);g.setColorAt(1,Qt::black);p.fillRect(3,5,18,14,g);p.drawRect(3,5,18,14);}
    else if(kind=="blur"){QPainterPath v;v.moveTo(12,2);v.cubicTo(8,9,3,12,5,18);v.cubicTo(7,25,22,22,19,14);v.closeSubpath();p.drawPath(v);}
    else if(kind=="dodge"){p.drawEllipse(10,3,11,11);p.drawLine(4,22,14,12);}
    else if(kind=="pen"){p.drawPolygon(QPolygonF{{3,21},{7,6},{19,3},{22,15}});p.drawLine(3,21,13,11);p.drawEllipse(11,9,4,4);}
    else if(kind=="text"){QFont f=p.font();f.setPixelSize(23);f.setBold(true);p.setFont(f);p.drawText(pixmap.rect(),Qt::AlignCenter,"T");}
    else if(kind=="shape")p.drawRect(4,4,16,16);
    else if(kind=="ellipseShape")p.drawEllipse(3,5,18,14);
    else if(kind=="hand")p.drawPolyline(QPolygonF{{5,20},{2,12},{5,10},{8,14},{8,5},{11,4},{12,11},{12,2},{15,2},{15,11},{16,4},{19,5},{19,13},{20,8},{23,10},{22,17},{18,22},{9,22},{5,20}});
    else if(kind=="zoom"){p.drawEllipse(3,3,13,13);p.drawLine(14,14,22,22);}
    else if(kind=="history"){p.drawArc(3,3,18,18,30*16,290*16);p.drawPolyline(QPolygonF{{3,4},{3,11},{10,11}});p.drawLine(12,6,12,12);p.drawLine(12,12,17,15);}
    return QIcon(pixmap);
}
class EditorToolButton final : public QToolButton {
public:
    explicit EditorToolButton(QWidget *parent):QToolButton(parent){}
protected:
    void mousePressEvent(QMouseEvent *event) override {
        if(menu() && event->button()==Qt::LeftButton && event->position().x()>=width()-12 && event->position().y()>=height()-11){menu()->exec(mapToGlobal(QPoint(width(),height())));event->accept();return;}
        QToolButton::mousePressEvent(event);
    }
};
class EditorRuler final : public QWidget {
public:
    EditorRuler(ImageEditorCanvas *canvas,bool vertical,QWidget *parent):QWidget(parent),canvas_(canvas),vertical_(vertical){if(vertical)setFixedWidth(22);else setFixedHeight(22);setProperty("cursorVisible",false);connect(canvas,&ImageEditorCanvas::viewChanged,this,qOverload<>(&QWidget::update));connect(canvas,&ImageEditorCanvas::cursorPositionChanged,this,[this](QPointF point,bool visible){cursor_=vertical_?point.y():point.x();cursorVisible_=visible;setProperty("cursorValue",cursor_);setProperty("cursorVisible",visible);update();});}
protected:
    void paintEvent(QPaintEvent *) override {
        QPainter p(this);p.fillRect(rect(),QColor("#383838"));p.setPen(QColor("#bbb"));QFont f=p.font();f.setPixelSize(9);p.setFont(f);const auto start=canvas_->documentPoint({0,0});const double zoom=canvas_->zoom();double step=std::pow(10.,std::floor(std::log10(std::max(1.,70/zoom))));if(step*zoom<35)step*=5;else if(step*zoom<65)step*=2;const double first=vertical_?start.y():start.x();const int length=vertical_?height():width();
        for(double value=std::floor(first/step)*step;value<=first+length/zoom;value+=step){const int at=qRound((value-first)*zoom);if(vertical_){p.drawLine(12,at,21,at);p.save();p.translate(11,at+3);p.rotate(-90);p.drawText(0,0,QString::number(value,'f',0));p.restore();}else{p.drawLine(at,13,at,21);p.drawText(at+3,11,QString::number(value,'f',0));}for(int i=1;i<5;++i){const int sub=at+qRound(i*step*zoom/5);if(vertical_)p.drawLine(17,sub,21,sub);else p.drawLine(sub,17,sub,21);}}
        if(cursorVisible_){const int at=qRound((cursor_-first)*zoom);p.setPen(QColor("#eee"));if(vertical_){p.drawLine(0,at,width(),at);p.setBrush(QColor("#eee"));p.drawPolygon(QPolygonF{{21.,double(at)},{16.,double(at-4)},{16.,double(at+4)}});}else{p.drawLine(at,0,at,height());p.setBrush(QColor("#eee"));p.drawPolygon(QPolygonF{{double(at),21.},{double(at-4),16.},{double(at+4),16.}});}}
    }
private: ImageEditorCanvas *canvas_;bool vertical_;double cursor_=0;bool cursorVisible_=false;
};
class BlendRangeSlider final : public QWidget {
public:
    BlendRangeSlider(QWidget *parent,std::function<void(ImageBlendRange)> changed):QWidget(parent),changed_(std::move(changed)){setMinimumHeight(40);setMinimumWidth(320);setToolTip(QObject::tr("拖动黑白端点；Alt 拖动拆分端点，设置渐变过渡。"));}
    void setRange(ImageBlendRange range){range_=range;update();}
protected:
    void paintEvent(QPaintEvent *) override{QPainter p(this);const QRect bar(8,4,width()-16,16);QLinearGradient g(bar.left(),0,bar.right(),0);g.setColorAt(0,Qt::black);g.setColorAt(1,Qt::white);p.fillRect(bar,g);p.setPen(QColor("#999"));p.drawRect(bar);for(int i=0;i<4;++i){const double x=8+range_[i]*(width()-16);p.setBrush(i<2?QColor("#222"):QColor("#eee"));const double y=i%2?32:24;p.drawPolygon(QPolygonF{{x,y-4},{x-5,y+4},{x+5,y+4}});}}
    void mousePressEvent(QMouseEvent *e) override{if(e->button()!=Qt::LeftButton)return;const double position=std::clamp((e->position().x()-8)/(width()-16),0.,1.);handle_=0;for(int i=1;i<4;++i)if(std::abs(range_[i]-position)<std::abs(range_[handle_]-position))handle_=i;paired_=!e->modifiers().testFlag(Qt::AltModifier);if(!paired_&&range_[0]==range_[1]&&handle_<2)handle_=1;else if(!paired_&&range_[2]==range_[3]&&handle_>=2)handle_=2;drag(e->position());}
    void mouseMoveEvent(QMouseEvent *e) override{if(e->buttons().testFlag(Qt::LeftButton)&&handle_>=0)drag(e->position());}
    void mouseReleaseEvent(QMouseEvent *) override{handle_=-1;}
private:
    void drag(QPointF point){const float value=float(std::clamp((point.x()-8)/(width()-16),0.,1.));if(paired_){const int begin=handle_<2?0:2;const float delta=value-range_[handle_];const float shift=std::clamp(delta,begin==0?-range_[0]:range_[1]-range_[2],begin==0?range_[2]-range_[1]:1-range_[3]);range_[begin]+=shift;range_[begin+1]+=shift;}else range_[handle_]=std::clamp(value,handle_?range_[handle_-1]:0.f,handle_<3?range_[handle_+1]:1.f);changed_(range_);update();}
    ImageBlendRange range_{0,0,1,1};std::function<void(ImageBlendRange)> changed_;int handle_=-1;bool paired_=true;
};
class EditorColorField final : public QWidget {
public:
    EditorColorField(QWidget *parent,std::function<void(QColor)> changed):QWidget(parent),changed_(std::move(changed)){setMinimumHeight(150);}
    void setColor(QColor value){color_=value;update();}
protected:
    void paintEvent(QPaintEvent *) override{QPainter p(this);const QRect field(0,0,width()-23,height());p.fillRect(field,QColor::fromHsvF(std::max(0.,double(color_.hsvHueF())),1,1));QLinearGradient w(0,0,field.width(),0);w.setColorAt(0,Qt::white);w.setColorAt(1,Qt::transparent);p.fillRect(field,w);QLinearGradient b(0,0,0,height());b.setColorAt(0,Qt::transparent);b.setColorAt(1,Qt::black);p.fillRect(field,b);for(int y=0;y<height();++y)p.fillRect(QRect(width()-17,y,17,1),QColor::fromHsvF(double(y)/height(),1,1));const QPointF at(color_.hsvSaturationF()*field.width(),(1-color_.valueF())*height());p.setPen(QPen(Qt::black,2));p.drawEllipse(at,4,4);p.setPen(Qt::white);p.drawEllipse(at,3,3);}
    void mousePressEvent(QMouseEvent *e) override{pick(e->position());}
    void mouseMoveEvent(QMouseEvent *e) override{if(e->buttons().testFlag(Qt::LeftButton))pick(e->position());}
private:
    void pick(QPointF at){const bool hue=at.x()>width()-22;color_=QColor::fromHsvF(hue?std::clamp(at.y()/height(),0.,.999999):std::max(0.,double(color_.hsvHueF())),hue?color_.hsvSaturationF():std::clamp(at.x()/std::max(1,width()-23),0.,1.),hue?color_.valueF():std::clamp(1-at.y()/height(),0.,1.));changed_(color_);update();}
    QColor color_=Qt::black;std::function<void(QColor)> changed_;
};
QWidget *optionGroup(QToolBar *bar){auto *w=new QWidget(bar);auto *l=new QHBoxLayout(w);l->setContentsMargins(0,0,0,0);l->setSpacing(5);bar->addWidget(w);return w;}
