ImageEditorWindow::ImageEditorWindow(const QImage &image,const QString &sourcePath,QWidget *parent):QMainWindow(parent),sourcePath_(sourcePath){document_=new ImageDocument(image.size(),precisionFor(image),this);document_->setColorSpace(image.colorSpace());document_->setMetadata("sourcePath",sourcePath);const auto id=document_->addLayer(tr("背景"),image);auto layer=activeLayer(document_,id);layer.locked=true;document_->updateLayer(layer);document_->history()->clear();document_->history()->setClean();buildUi();}
ImageEditorWindow::ImageEditorWindow(ImageDocument *document,const QString &sourcePath,QWidget *parent):QMainWindow(parent),document_(document),sourcePath_(sourcePath){document_->setParent(this);buildUi();}
ImageEditorWindow::~ImageEditorWindow(){for(const auto &page:pages_){disconnect(page.document,nullptr,this,nullptr);disconnect(page.document->history(),nullptr,this,nullptr);disconnect(page.tools,nullptr,this,nullptr);disconnect(page.canvas,nullptr,this,nullptr);}}
