void ImageEditorWindow::openImage(){
    const auto path=QFileDialog::getOpenFileName(this,tr("打开图像"),QFileInfo(sourcePath_).absolutePath(),tr("图像 (*.png *.jpg *.jpeg *.webp *.avif *.tif *.tiff *.bmp *.psd *.psb);;所有文件 (*)"));if(path.isEmpty())return;for(int i=0;i<pages_.size();++i)if(QFileInfo(pages_[i].path).absoluteFilePath().compare(QFileInfo(path).absoluteFilePath(),Qt::CaseInsensitive)==0){activateDocument(i);return;}
    const auto suffix=QFileInfo(path).suffix().toLower();if(suffix!="psd" && suffix!="psb"){
        auto *decoder=new PlayerImage(qApp);QPointer<ImageEditorWindow> owner(this);statusBar()->showMessage(tr("正在读取图像…"));
        connect(decoder,&PlayerImage::loaded,qApp,[owner,path,decoder](const QImage &image){decoder->deleteLater();if(!owner)return;owner->updateStatus();owner->addImage(image,path);});
        connect(decoder,&PlayerImage::failed,qApp,[owner,decoder](const QString &error){decoder->deleteLater();if(owner){owner->updateStatus();QMessageBox::warning(owner,tr("打开图像"),error);}});decoder->open(path);return;
    }
    struct Result{std::unique_ptr<ImageDocument> document;QString error;QStringList warnings;};auto result=std::make_shared<Result>();QPointer<ImageEditorWindow> owner(this);statusBar()->showMessage(tr("正在读取图像…"));
    auto *thread=QThread::create([path,result]{result->document=ImagePsd::load(path,&result->error,&result->warnings);if(result->document){const auto size=result->document->size();result->document->compositePreview(QRect(QPoint(),size),size.scaled({640,900},Qt::KeepAspectRatio));result->error=result->document->storageError();result->document->moveToThread(qApp->thread());}});
    connect(thread,&QThread::finished,qApp,[owner,result,path]{if(!owner)return;owner->updateStatus();if(!result->error.isEmpty()){QMessageBox::warning(owner,tr("打开图像"),result->error);return;}owner->addDocument(result->document.release(),path);if(!result->warnings.isEmpty())QMessageBox::information(owner,tr("PSD 导入说明"),result->warnings.join('\n'));});connect(thread,&QThread::finished,thread,&QObject::deleteLater);thread->start();
}
