void ImageEditorWindow::exportDocument(bool floating) {
    canvas_->cancelGesture();
    const auto path=QFileDialog::getSaveFileName(this,floating?tr("导出浮点 TIFF"):tr("另存图层工程"),QFileInfo(sourcePath_).absolutePath()+"/"+QFileInfo(sourcePath_).completeBaseName()+(floating?"-edited.tif":"-edited.psd"),floating?tr("TIFF (*.tif *.tiff)"):tr("Photoshop PSD (*.psd);;Photoshop PSB (*.psb)"));
    if(path.isEmpty())return;
    if(isSourcePath(path)){QMessageBox::warning(this,tr("导出图像"),tr("请选择新路径以保留源文件。"));return;}
    auto snapshot=std::shared_ptr<ImageDocument>(document_->snapshot().release());const auto revision=document_->revision();QPointer<ImageDocument> exportingDocument(document_);auto result=std::make_shared<QString>();
    auto *thread=QThread::create([snapshot,path,floating,result]() mutable {if(floating)ImageHdr::exportFloatTiff(snapshot.get(),path,result.get());else *result=ImagePsd::save(snapshot.get(),path);snapshot.reset();});snapshot->moveToThread(thread);
    auto *saveAction=findChild<QAction *>(floating?"imageEditorExportFloat":"imageEditorSavePsd");saveAction->setEnabled(false);statusBar()->showMessage(tr("正在后台保存图像…"));
    connect(thread,&QThread::finished,this,[this,result,revision,floating,saveAction,exportingDocument]{saveAction->setEnabled(true);if(!result->isEmpty())QMessageBox::warning(this,tr("保存图像"),*result);else{if(!floating && exportingDocument && exportingDocument->revision()==revision)exportingDocument->history()->setClean();statusBar()->showMessage(tr("图像已保存。"),5000);}});
    connect(thread,&QThread::finished,thread,&QObject::deleteLater);snapshot.reset();thread->start();
}
void ImageEditorWindow::savePng(){canvas_->cancelGesture();const auto path=QFileDialog::getSaveFileName(this,tr("导出扁平 PNG(不含图层和历史)"),QFileInfo(sourcePath_).absolutePath()+"/"+QFileInfo(sourcePath_).completeBaseName()+"-edited.png",tr("PNG (*.png)"));if(path.isEmpty())return;if(isSourcePath(path)){QMessageBox::warning(this,tr("导出图像"),tr("请选择新路径，避免覆盖源文件。"));return;}const auto error=ImageEditorTools::savePng(document_,path);if(!error.isEmpty())QMessageBox::warning(this,tr("PNG 导出"),error);else statusBar()->showMessage(tr("已导出扁平 PNG；图层与历史保留在窗口中。"),5000);}
