        case ImageAdjustmentKind::Curves:{auto *tabs=new QTabWidget(&dialog);const QStringList channels{tr("RGB"),tr("红"),tr("绿"),tr("蓝")};for(int c=0;c<4;++c){auto *page=new QWidget(tabs);auto *column=new QVBoxLayout(page);auto *plot=new QLabel(page);plot->setFixedHeight(110);column->addWidget(plot);auto *table=new QTableWidget(5,2,page);table->setObjectName("imageEditorCurve_"+QString::number(c));table->setHorizontalHeaderLabels({tr("输入"),tr("输出")});for(int row=0;row<5;++row)for(int col=0;col<2;++col)table->setItem(row,col,new QTableWidgetItem(QString::number(row*.25)));column->addWidget(table);auto redraw=[table,plot]{QPixmap image(460,110);image.fill(QColor("#383838"));QPainter p(&image);p.setPen(QColor("#444"));for(int x=0;x<=4;++x)p.drawLine(x*114,0,x*114,109);for(int y=0;y<=4;++y)p.drawLine(0,y*27,459,y*27);p.setPen(QPen(QColor("#ddd"),2));QPolygonF points;for(int row=0;row<table->rowCount();++row){const auto *a=table->item(row,0),*b=table->item(row,1);if(a&&b)points<<QPointF(a->text().toDouble()*459,(1-b->text().toDouble())*109);}p.drawPolyline(points);plot->setPixmap(image);};connect(table,&QTableWidget::cellChanged,page,[redraw](int,int){redraw();});auto *row=new QHBoxLayout;auto *add=new QPushButton(tr("添加控制点"),page),*remove=new QPushButton(tr("删除控制点"),page);row->addWidget(add);row->addWidget(remove);column->addLayout(row);connect(add,&QPushButton::clicked,page,[table]{const int row=table->currentRow()<0?table->rowCount():table->currentRow()+1;table->insertRow(row);table->setItem(row,0,new QTableWidgetItem("0.5"));table->setItem(row,1,new QTableWidgetItem("0.5"));});connect(remove,&QPushButton::clicked,page,[table]{if(table->currentRow()>=0)table->removeRow(table->currentRow());});curves.append(table);redraw();tabs->addTab(page,channels[c]);}layout.addWidget(tabs);layout.addWidget(new QLabel(tr("输入点必须递增；HDR 超出范围使用端点斜率外推。"),&dialog));break;}
        case ImageAdjustmentKind::HueSaturation:number(tr("色相(度)"),"hue",spec.hue,-360,360);number(tr("饱和度倍率"),"saturation",spec.saturation,0,10);number(tr("明度"),"lightness",spec.lightness,-10,10);break;
